import { sql } from "drizzle-orm";
import type { Database } from "./client";
import { MIGRATIONS } from "./migrations.generated";

/** Advisory-lock id so concurrent cold starts never run migrations twice. */
const MIGRATION_LOCK_ID = 727190441;

export function rowsOf<T>(result: unknown): T[] {
  if (Array.isArray(result)) return result as T[];
  const rows = (result as { rows?: T[] } | null)?.rows;
  return Array.isArray(rows) ? rows : [];
}

/**
 * Applies pending migrations (generated by drizzle-kit, embedded at build time).
 * Book-keeping is compatible with drizzle-orm's own migrator table.
 */
export async function runMigrations(db: Database): Promise<number> {
  return db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(${MIGRATION_LOCK_ID})`);
    await tx.execute(sql`create schema if not exists drizzle`);
    await tx.execute(
      sql`create table if not exists drizzle.__drizzle_migrations (id serial primary key, hash text not null, created_at bigint)`,
    );
    const last = rowsOf<{ created_at: string | number | null }>(
      await tx.execute(
        sql`select created_at from drizzle.__drizzle_migrations order by created_at desc limit 1`,
      ),
    )[0];
    const lastApplied = last?.created_at == null ? -1 : Number(last.created_at);

    let applied = 0;
    for (const migration of MIGRATIONS) {
      if (migration.when <= lastApplied) continue;
      for (const statement of migration.statements) {
        await tx.execute(sql.raw(statement));
      }
      await tx.execute(
        sql`insert into drizzle.__drizzle_migrations (hash, created_at) values (${migration.hash}, ${migration.when})`,
      );
      applied++;
    }
    if (applied > 0) console.info(`[db] Applied ${applied} migration(s).`);
    return applied;
  });
}
